text:
{
  "name": "잔향구역",
  "genre": "공포/추리",
  "subgenre": "현대 도시 괴이 수사극",
  "tone": "건조하고 서늘하며, 부조리를 담담히 기록하는 가벼운 유머",
  "era": "가까운 미래, 대규모 침수와 도시 재편 이후 8년",
  "techLevel": "현재보다 조금 발달한 도시 감시망·재난 예측 기술. 초자연 현상 자체를 측정하는 기술은 없으며, 휴대전화·드론·공공 기록 시스템은 불완전한 전력망에 의존한다.",
  "regions": "해안 대도시 해원시와 이를 둘러싼 격리 구역들. 구도심 저지대는 물이 빠진 뒤에도 밤마다 낯선 골목과 출입구가 나타나는 잔향구역으로 분류된다. 고지대 행정구, 항만 재건지, 임시 거주촌, 폐쇄된 지하철 노선이 서로 다른 생활권을 이룬다.",
  "societyForm": "재난 이후 시청·민간 복구기업·주민 자치회가 권한을 나눠 가진 도시 사회. 통행증과 기록 접근권이 생존 자원이며, 공식 수사와 사적 생계가 자주 충돌한다.",
  "premise": "8년 전 해원시를 덮친 ‘긴 만조’는 여러 구역을 침수시키고, 일부 주민과 건물을 기록에서 지웠다. 물이 빠진 뒤에도 구도심에는 지도에 없는 복도와 골목이 간헐적으로 연결되었고, 그 안에서 실종자의 목소리나 이미 폐기된 안내 방송이 들리기 시작했다. 시청은 이를 재난 후유증과 불법 점거로 분류하지만, 잔향구역에서 발견된 사건들은 서로 다른 시기와 장소의 실종 기록을 잇는다. 플레이어는 형사, 구역 조사관, 주민 기록관, 복구업체 현장요원, 무소속 생존자 등으로 살아가며 사건의 증거를 모은다. 각 역할은 서로 다른 기록과 접근권을 갖고, 진실을 밝히는 일은 누군가의 집과 생계, 혹은 공식적인 과거를 무너뜨릴 수 있다. 판정은 관찰·기록·대인관계·현장대응 같은 능력치와 주사위로 처리되지만, 성공은 사실을 얻는 일이지 안전을 보장하는 일이 아니다.",
  "centralPremise": "도시의 기록에서 사라진 사람들을 추적할수록, 진실을 공개하는 일이 살아 있는 이들의 거처와 신분까지 지워 버릴 수 있다.",
  "situation": {
    "biggestEvent": "긴 만조 당시 해원시의 저지대 세 구역이 한밤중에 물에 잠겼고, 공식 사망자 명단에는 존재하지 않는 사람이 수백 명 포함됐다는 증언이 남았다. 재난 통신망의 마지막 11분은 복구되지 않았다. 이후 특정 날짜와 기상 조건에 구도심의 건물 구조가 맞지 않게 이어지는 현상이 반복되며, 주민들은 이를 잔향이라 부른다. 잔향 안에서 얻은 물건과 음성은 바깥의 기록과 일치할 때도, 수십 년 전 문서와 일치할 때도 있다.",
    "beneficiaries": "시청은 잔향구역을 위험 통제 구역으로 지정해 토지와 통행을 관리한다. 복구기업은 구역 철거·감시 계약으로 수익을 얻고, 주민 자치회 일부는 통행증과 임시 거처를 배분하며 지역의 질서를 유지한다. 조사관과 기록관은 공식 문서에 남지 않은 사건을 해결해 신뢰를 얻을 수 있지만, 자신이 가진 정보가 누구의 몫인지 계속 협상해야 한다.",
    "threatened": "저지대 주민, 무등록 생존자, 실종자 가족은 주소와 법적 신분을 잃을 위험에 놓여 있다. 잔향구역에서 돌아온 사람은 자신이 며칠을 보냈는지 설명하지 못하거나, 주변인이 기억하는 과거와 다른 말을 하기도 한다. 수사팀 역시 현장에 오래 머물수록 녹음·사진·증언이 서로 어긋나고, 한 명의 진술을 믿는 순간 다른 관계를 잃을 수 있다.",
    "upcomingChange": "시청은 다음 분기부터 잔향구역의 영구 봉쇄와 주민 재등록을 시행하려 한다. 같은 시기에 봉쇄 예정 구역에서 긴 만조 당일의 원본 통신 기록이 발견됐다는 제보가 들어온다. 기록을 확보하면 재난의 책임과 실종자 명단을 재검토할 수 있지만, 공개될 경우 현재 거주자 일부의 법적 권리가 무효가 될 수 있다. 서로 다른 세력은 기록을 찾으려 하면서도, 공개 여부와 공개 시점을 두고 갈라지고 있다."
  },
  "factions": [
    {
      "name": "해원시 잔향관리과",
      "purpose": "잔향구역의 출입을 통제하고 실종·괴이 사건을 재난 후유증의 범주 안에서 처리한다.",
      "leadership": "시청 안전국 산하 과장과 구역별 현장 책임자. 책임자는 정기 인사로 교체되며 현장 판단의 책임은 개인에게 남는다.",
      "means": "통행 허가증, 격리선, 사건 보고서, CCTV 열람권을 관리한다. 등록 조사관을 파견하고 언론 발표의 문구를 검토한다.",
      "relations": "복구기업과 계약상 협력하지만 철거 우선순위를 두고 다툰다. 주민 자치회와는 통행 문제로 마찰하며, 형사에게는 제한된 기록만 제공한다.",
      "publicView": "구역 밖 주민에게는 필요한 안전 조직이다. 저지대 주민에게는 위험을 막는 곳이자, 불편한 질문을 서류로 멈추는 곳이다."
    },
    {
      "name": "해원경찰청 미제사건팀",
      "purpose": "잔향구역에서 발생한 살인·실종·사기 사건을 일반 범죄의 기준으로 수사하고 피해자의 신원을 확인한다.",
      "leadership": "경찰청 수사부장 아래 소수의 형사와 기록 분석관이 팀을 이룬다. 외부 조사관은 사건별 협력자로 등록된다.",
      "means": "영장, 증거물 보관소, 목격자 면담, 현장 감식 권한을 사용한다. 초자연 현상을 증거로 인정하지 않지만, 물리적 흔적과 서로 독립된 진술은 추적한다.",
      "relations": "잔향관리과의 자료 제한에 불만이 있고, 주민 자치회와는 비공식 제보망을 유지한다. 복구기업의 계약 자료를 요구할 때 자주 거부당한다.",
      "publicView": "사건을 맡으면 끝까지 간다는 평과, 끝까지 가도 결론을 발표하지 못한다는 평을 함께 듣는다."
    },
    {
      "name": "저지대 주민연합",
      "purpose": "임시 거주권과 생계 기반을 지키고, 실종자 가족과 무등록 생존자를 공동체 안에 남겨 둔다.",
      "leadership": "각 거주촌 대표와 순번제 조정위원으로 구성된다. 공식 대표가 모든 주민을 대신한다고 주장하지 않는다.",
      "means": "구호 물자, 안전한 숙소, 구전 지도, 야간 순찰을 나눈다. 외부 조사에는 동행자를 붙이고 증언 공개 여부를 당사자와 협의한다.",
      "relations": "시청과는 등록 기준을 두고 대립하면서도 구호 배급에 의존한다. 미제사건팀에는 제한적으로 협조하며, 복구기업의 철거 작업에는 강하게 반발한다.",
      "publicView": "지역 안에서는 서로를 지키는 이웃이다. 바깥에서는 폐쇄적이고 규칙이 많은 집단으로 보인다."
    },
    {
      "name": "백조복구 컨소시엄",
      "purpose": "침수 구역을 복구하고 잔향구역을 안정화해 부동산과 기반 시설을 다시 운용한다.",
      "leadership": "복수의 건설·통신 기업이 이사회로 운영하며, 현장에는 안전 관리자와 계약 조사팀을 둔다.",
      "means": "중장비, 수중 센서, 사설 경비, 토지 계약, 재난 데이터 분석을 활용한다. 조사 결과를 공개하기보다 계약 당사자에게 먼저 제공한다.",
      "relations": "잔향관리과의 주요 계약자지만 일정과 책임 소재를 두고 갈등한다. 주민연합과는 토지 권리 문제로 대치하고, 형사 수사에는 법무팀을 통해 대응한다.",
      "publicView": "일자리를 제공하고 도시를 다시 세우는 회사라는 인식과, 복구를 핑계로 사람을 밀어낸다는 불신이 공존한다."
    },
    {
      "name": "야간기록회",
      "purpose": "공식 기록에서 빠진 이름, 주소, 증언을 보존하고 서로 다른 실종 사건의 연결을 추적한다.",
      "leadership": "사서, 전직 기자, 주민 기록관들이 느슨한 운영회를 이루며 고정된 지도자는 없다.",
      "means": "종이 장부, 중복 저장된 녹음, 가족 문서, 구전 대조표를 사용한다. 기록을 한 곳에 모으지 않고 여러 사람에게 나눠 맡긴다.",
      "relations": "미제사건팀과 증거를 교환하지만 공개 시점에 의견이 갈린다. 주민연합과는 신뢰를 쌓고, 시청과 컨소시엄은 이들의 자료를 무단 유통으로 간주한다.",
      "publicView": "잃어버린 이름을 기억하는 사람들로 존중받지만, 소문과 사실을 섞는다는 의심도 받는다."
    }
  ],
  "powerSystem": {
    "capabilities": "이 세계의 영향력은 초자연적 재능이 아니라 접근 권한, 신뢰, 전문 기술, 기록의 진위로 형성된다. 수사에는 관찰·기록·대인관계·현장대응 능력치를 쓰며, 주사위 판정은 준비도와 위험을 반영한다. 성공하면 단서나 협조를 얻고, 실패하면 시간·안전·관계 중 하나를 잃거나 잘못된 정보를 확신할 수 있다.",
    "users": "형사, 잔향구역 조사관, 주민 기록관, 복구업체 기술자, 구호 담당자, 무소속 생존자 등. 각 직업은 서로 다른 장소와 문서에 접근할 수 있어 단독으로 사건 전체를 파악하지 못한다.",
    "acquisition": "자격증과 소속으로 공식 권한을 얻거나, 봉사와 거래를 통해 주민의 신뢰를 쌓거나, 숙련된 기술과 검증 가능한 기록으로 협조를 확보한다. 잔향구역의 경험은 전문성을 높일 수 있지만 자동으로 신뢰나 면책을 주지는 않는다.",
    "ranks": "공식 조사 권한은 등록 외부인, 구역 조사관, 현장 책임자, 수사 책임자로 나뉜다. 주민 사회의 영향력은 직급 대신 맡은 역할과 상호 보증으로 정해진다. 기록회의 내부에는 고정 계급이 없으며, 서로 다른 출처로 확인된 자료일수록 더 큰 무게를 얻는다.",
    "limits": "허가증은 지정 구역과 시간에만 유효하고, 경찰 영장도 잔향 내부의 구조 변경이나 기록 불일치를 해결하지 못한다. 한 출처의 진술만으로 사람의 신원이나 사건의 결론을 확정할 수 없다. 능력치가 높아도 기억의 어긋남, 장비 고장, 이해관계자의 침묵을 제거하지 못한다.",
    "costs": "조사는 통행 기회와 신뢰를 소비하며, 깊은 구역에 오래 머물면 기록 간 모순과 수면 부족, 동료에 대한 의심이 쌓인다. 공식 기록을 훼손하거나 무단 공개하면 면허·직업·거주권을 잃을 수 있다. 중요한 단서를 지키려면 다른 단서나 관계를 포기해야 할 때가 있다.",
    "socialImpact": "누구의 보고서가 공식 사실이 되는지는 거주권, 보상금, 실종자 지위, 철거 여부를 바꾼다. 따라서 조사 능력은 영웅적 힘보다 사회적 책임에 가깝다. 플레이어는 여러 인물을 맡아 한 세계의 서로 다른 결론과 증언을 만들 수 있으며, 이전 인물의 선택은 다음 인물의 접근권과 평판에 영향을 준다.",
    "taboos": "당사자 동의 없이 실종자의 이름이나 음성을 공개하지 않는다. 잔향 안에서 얻은 물건을 원래 출처를 확인하지 않고 증거물로 제출하지 않는다. 목격자를 ‘미친 사람’이나 ‘괴이한 존재’로 단정하지 않으며, 서로 모순되는 자료를 하나의 깔끔한 보고서로 덮지 않는다."
  },
  "society": {
    "계급과 거주권": "시민 등록 상태와 주소가 배급·치료·통행 권리를 좌우한다. 고지대 정식 거주자, 재난 이주민, 임시 거주자, 무등록 생존자 사이의 차이는 법적이면서도 일상적이다. 조사자는 누구의 신분을 먼저 확인할지 선택해야 한다.",
